-- Kisan Pathshala MySQL 8.0 schema.
-- Select the kisan_pathshala database before applying this file.
-- UUID values are generated by the application and stored as CHAR(36).
-- Use UTC for application/database connections.
USE kisan_pathshala;

CREATE TABLE IF NOT EXISTS users (
	id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	email VARCHAR(254) NOT NULL,
	password_hash VARCHAR(255) CHARACTER SET ascii COLLATE ascii_bin NULL,
	email_verified_at DATETIME(6) NULL,
	status VARCHAR(16) NOT NULL DEFAULT 'active',
	last_login_at DATETIME(6) NULL,
	created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
	updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6)
		ON UPDATE CURRENT_TIMESTAMP(6),
	PRIMARY KEY (id),
	UNIQUE KEY uq_users_email (email),
	CONSTRAINT chk_users_status CHECK (status IN ('active', 'disabled'))
) ENGINE=InnoDB DEFAULT CHARACTER SET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS profiles (
	id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	full_name VARCHAR(255) NOT NULL,
	phone VARCHAR(32) NULL,
	preferred_language VARCHAR(2) NOT NULL DEFAULT 'en',
	role VARCHAR(16) NOT NULL DEFAULT 'farmer',
	created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
	updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6)
		ON UPDATE CURRENT_TIMESTAMP(6),
	PRIMARY KEY (id),
	UNIQUE KEY uq_profiles_phone (phone),
	UNIQUE KEY uq_profiles_id_role (id, role),
	KEY idx_profiles_role (role),
	CONSTRAINT fk_profiles_user FOREIGN KEY (id)
		REFERENCES users (id) ON DELETE CASCADE,
	CONSTRAINT chk_profiles_full_name CHECK (CHAR_LENGTH(TRIM(full_name)) > 0),
	CONSTRAINT chk_profiles_language CHECK (preferred_language IN ('en', 'hi')),
	CONSTRAINT chk_profiles_role CHECK (role IN ('farmer', 'admin'))
) ENGINE=InnoDB DEFAULT CHARACTER SET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS oauth_identities (
	id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	provider VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	provider_subject VARCHAR(255) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	provider_email VARCHAR(254) NULL,
	provider_email_verified BOOLEAN NOT NULL DEFAULT FALSE,
	created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
	updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6)
		ON UPDATE CURRENT_TIMESTAMP(6),
	PRIMARY KEY (id),
	UNIQUE KEY uq_oauth_provider_subject (provider, provider_subject),
	KEY idx_oauth_identities_user (user_id),
	CONSTRAINT fk_oauth_identities_user FOREIGN KEY (user_id)
		REFERENCES users (id) ON DELETE CASCADE,
	CONSTRAINT chk_oauth_provider CHECK (provider IN ('google'))
) ENGINE=InnoDB DEFAULT CHARACTER SET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS sessions (
	id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	token_hash BINARY(32) NOT NULL,
	csrf_token_hash BINARY(32) NULL,
	created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
	last_seen_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
	expires_at DATETIME(6) NOT NULL,
	revoked_at DATETIME(6) NULL,
	user_agent VARCHAR(512) NULL,
	PRIMARY KEY (id),
	UNIQUE KEY uq_sessions_token_hash (token_hash),
	KEY idx_sessions_user_expiry (user_id, expires_at),
	KEY idx_sessions_expiry (expires_at),
	CONSTRAINT fk_sessions_user FOREIGN KEY (user_id)
		REFERENCES users (id) ON DELETE CASCADE,
	CONSTRAINT chk_sessions_expiry CHECK (expires_at > created_at)
) ENGINE=InnoDB DEFAULT CHARACTER SET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS courses (
	id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	slug VARCHAR(255) NOT NULL,
	title_en VARCHAR(255) NOT NULL,
	title_hi VARCHAR(255) NOT NULL,
	description_en TEXT NOT NULL DEFAULT (''),
	description_hi TEXT NOT NULL DEFAULT (''),
	category VARCHAR(120) NULL,
	level VARCHAR(16) NOT NULL DEFAULT 'beginner',
	status VARCHAR(16) NOT NULL DEFAULT 'draft',
	display_order INT NOT NULL DEFAULT 0,
	created_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
	published_at DATETIME(6) NULL,
	created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
	updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6)
		ON UPDATE CURRENT_TIMESTAMP(6),
	PRIMARY KEY (id),
	UNIQUE KEY uq_courses_slug (slug),
	KEY idx_courses_status_order (status, display_order),
	KEY idx_courses_created_by (created_by),
	CONSTRAINT fk_courses_created_by FOREIGN KEY (created_by)
		REFERENCES profiles (id) ON DELETE SET NULL,
	CONSTRAINT chk_courses_slug CHECK (CHAR_LENGTH(TRIM(slug)) > 0),
	CONSTRAINT chk_courses_title_en CHECK (CHAR_LENGTH(TRIM(title_en)) > 0),
	CONSTRAINT chk_courses_title_hi CHECK (CHAR_LENGTH(TRIM(title_hi)) > 0),
	CONSTRAINT chk_courses_level CHECK (level IN ('beginner', 'intermediate', 'advanced')),
	CONSTRAINT chk_courses_status CHECK (status IN ('draft', 'published', 'archived'))
) ENGINE=InnoDB DEFAULT CHARACTER SET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS course_modules (
	id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	course_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	title_en VARCHAR(255) NOT NULL,
	title_hi VARCHAR(255) NOT NULL,
	description_en TEXT NOT NULL DEFAULT (''),
	description_hi TEXT NOT NULL DEFAULT (''),
	display_order INT NOT NULL DEFAULT 0,
	created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
	updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6)
		ON UPDATE CURRENT_TIMESTAMP(6),
	PRIMARY KEY (id),
	UNIQUE KEY uq_course_modules_order (course_id, display_order),
	CONSTRAINT fk_course_modules_course FOREIGN KEY (course_id)
		REFERENCES courses (id) ON DELETE CASCADE,
	CONSTRAINT chk_course_modules_title_en CHECK (CHAR_LENGTH(TRIM(title_en)) > 0),
	CONSTRAINT chk_course_modules_title_hi CHECK (CHAR_LENGTH(TRIM(title_hi)) > 0),
	CONSTRAINT chk_course_modules_order CHECK (display_order >= 0)
) ENGINE=InnoDB DEFAULT CHARACTER SET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS lessons (
	id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	module_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	title_en VARCHAR(255) NOT NULL,
	title_hi VARCHAR(255) NOT NULL,
	description_en TEXT NOT NULL DEFAULT (''),
	description_hi TEXT NOT NULL DEFAULT (''),
	content_en LONGTEXT NOT NULL DEFAULT (''),
	content_hi LONGTEXT NOT NULL DEFAULT (''),
	content_type VARCHAR(16) NOT NULL DEFAULT 'article',
	content_url VARCHAR(2048) NULL,
	duration_minutes INT NULL,
	display_order INT NOT NULL DEFAULT 0,
	is_published BOOLEAN NOT NULL DEFAULT FALSE,
	created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
	updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6)
		ON UPDATE CURRENT_TIMESTAMP(6),
	PRIMARY KEY (id),
	UNIQUE KEY uq_lessons_module_order (module_id, display_order),
	CONSTRAINT fk_lessons_module FOREIGN KEY (module_id)
		REFERENCES course_modules (id) ON DELETE CASCADE,
	CONSTRAINT chk_lessons_title_en CHECK (CHAR_LENGTH(TRIM(title_en)) > 0),
	CONSTRAINT chk_lessons_title_hi CHECK (CHAR_LENGTH(TRIM(title_hi)) > 0),
	CONSTRAINT chk_lessons_content_type CHECK (content_type IN ('article', 'video', 'quiz')),
	CONSTRAINT chk_lessons_duration CHECK (duration_minutes IS NULL OR duration_minutes > 0),
	CONSTRAINT chk_lessons_order CHECK (display_order >= 0)
) ENGINE=InnoDB DEFAULT CHARACTER SET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS orders (
	id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	course_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	amount_paise BIGINT NOT NULL,
	currency CHAR(3) NOT NULL DEFAULT 'INR',
	payment_method VARCHAR(16) NOT NULL DEFAULT 'upi',
	payment_status VARCHAR(16) NOT NULL DEFAULT 'pending',
	upi_utr VARCHAR(128) NULL,
	utr_submitted_at DATETIME(6) NULL,
	reviewed_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
	reviewed_by_role VARCHAR(16) NULL,
	reviewed_at DATETIME(6) NULL,
	review_note TEXT NULL,
	created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
	updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6)
		ON UPDATE CURRENT_TIMESTAMP(6),
	PRIMARY KEY (id),
	UNIQUE KEY uq_orders_upi_utr (upi_utr),
	KEY idx_orders_user_created (user_id, created_at DESC),
	KEY idx_orders_course_status (course_id, payment_status),
	KEY idx_orders_reviewed_by_role (reviewed_by, reviewed_by_role),
	CONSTRAINT fk_orders_user FOREIGN KEY (user_id)
		REFERENCES users (id) ON DELETE RESTRICT,
	CONSTRAINT fk_orders_course FOREIGN KEY (course_id)
		REFERENCES courses (id) ON DELETE RESTRICT,
	CONSTRAINT fk_orders_reviewer_admin FOREIGN KEY (reviewed_by, reviewed_by_role)
		REFERENCES profiles (id, role) ON DELETE RESTRICT,
	CONSTRAINT chk_orders_amount CHECK (amount_paise > 0),
	CONSTRAINT chk_orders_currency CHECK (currency = 'INR'),
	CONSTRAINT chk_orders_method CHECK (payment_method = 'upi'),
	CONSTRAINT chk_orders_status CHECK (payment_status IN ('pending', 'submitted', 'verified', 'rejected')),
	CONSTRAINT chk_orders_utr_pair CHECK (
		(upi_utr IS NULL AND utr_submitted_at IS NULL)
		OR (upi_utr IS NOT NULL AND utr_submitted_at IS NOT NULL)
	),
	CONSTRAINT chk_orders_review_pair CHECK (
		(reviewed_by IS NULL AND reviewed_by_role IS NULL AND reviewed_at IS NULL)
		OR (reviewed_by IS NOT NULL AND reviewed_by_role IS NOT NULL
			AND reviewed_by_role = 'admin' AND reviewed_at IS NOT NULL)
	),
	CONSTRAINT chk_orders_reviewed_status CHECK (
		(payment_status IN ('verified', 'rejected')) = (reviewed_by IS NOT NULL)
	),
	CONSTRAINT chk_orders_pending_utr CHECK (
		(payment_status <> 'pending') OR upi_utr IS NULL
	)
) ENGINE=InnoDB DEFAULT CHARACTER SET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS enrollments (
	id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	course_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	order_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	status VARCHAR(16) NOT NULL DEFAULT 'pending',
	activated_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
	activated_by_role VARCHAR(16) NULL,
	activated_at DATETIME(6) NULL,
	created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
	updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6)
		ON UPDATE CURRENT_TIMESTAMP(6),
	PRIMARY KEY (id),
	UNIQUE KEY uq_enrollments_order (order_id),
	UNIQUE KEY uq_enrollments_user_course (user_id, course_id),
	KEY idx_enrollments_user_status (user_id, status),
	KEY idx_enrollments_course_status (course_id, status),
	KEY idx_enrollments_activator_role (activated_by, activated_by_role),
	CONSTRAINT fk_enrollments_user FOREIGN KEY (user_id)
		REFERENCES users (id) ON DELETE RESTRICT,
	CONSTRAINT fk_enrollments_course FOREIGN KEY (course_id)
		REFERENCES courses (id) ON DELETE RESTRICT,
	CONSTRAINT fk_enrollments_order FOREIGN KEY (order_id)
		REFERENCES orders (id) ON DELETE RESTRICT,
	CONSTRAINT fk_enrollments_activator_admin FOREIGN KEY (activated_by, activated_by_role)
		REFERENCES profiles (id, role) ON DELETE RESTRICT,
	CONSTRAINT chk_enrollments_status CHECK (status IN ('pending', 'active', 'suspended', 'cancelled')),
	CONSTRAINT chk_enrollments_activation_pair CHECK (
		(activated_by IS NULL AND activated_by_role IS NULL AND activated_at IS NULL)
		OR (activated_by IS NOT NULL AND activated_by_role IS NOT NULL
			AND activated_by_role = 'admin' AND activated_at IS NOT NULL)
	),
	CONSTRAINT chk_enrollments_active_activated CHECK (status <> 'active' OR activated_by IS NOT NULL)
) ENGINE=InnoDB DEFAULT CHARACTER SET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS lesson_progress (
	id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	lesson_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	is_completed BOOLEAN NOT NULL DEFAULT FALSE,
	completed_at DATETIME(6) NULL,
	created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
	updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6)
		ON UPDATE CURRENT_TIMESTAMP(6),
	PRIMARY KEY (id),
	UNIQUE KEY uq_lesson_progress_user_lesson (user_id, lesson_id),
	KEY idx_lesson_progress_user_completed (user_id, is_completed),
	CONSTRAINT fk_lesson_progress_user FOREIGN KEY (user_id)
		REFERENCES users (id) ON DELETE CASCADE,
	CONSTRAINT fk_lesson_progress_lesson FOREIGN KEY (lesson_id)
		REFERENCES lessons (id) ON DELETE CASCADE,
	CONSTRAINT chk_lesson_progress_completion CHECK (NOT is_completed OR completed_at IS NOT NULL)
) ENGINE=InnoDB DEFAULT CHARACTER SET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS certificates (
	id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	enrollment_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	course_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
	certificate_number VARCHAR(255) NOT NULL,
	issued_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
	issued_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
	revoked_at DATETIME(6) NULL,
	revoked_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
	created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
	PRIMARY KEY (id),
	UNIQUE KEY uq_certificates_enrollment (enrollment_id),
	UNIQUE KEY uq_certificates_number (certificate_number),
	KEY idx_certificates_user_issued (user_id, issued_at DESC),
	KEY idx_certificates_course (course_id),
	KEY idx_certificates_issued_by (issued_by),
	KEY idx_certificates_revoked_by (revoked_by),
	CONSTRAINT fk_certificates_enrollment FOREIGN KEY (enrollment_id)
		REFERENCES enrollments (id) ON DELETE RESTRICT,
	CONSTRAINT fk_certificates_user FOREIGN KEY (user_id)
		REFERENCES users (id) ON DELETE RESTRICT,
	CONSTRAINT fk_certificates_course FOREIGN KEY (course_id)
		REFERENCES courses (id) ON DELETE RESTRICT,
	CONSTRAINT fk_certificates_issuer FOREIGN KEY (issued_by)
		REFERENCES profiles (id) ON DELETE RESTRICT,
	CONSTRAINT fk_certificates_revoker FOREIGN KEY (revoked_by)
		REFERENCES profiles (id) ON DELETE RESTRICT,
	CONSTRAINT chk_certificates_number CHECK (CHAR_LENGTH(TRIM(certificate_number)) > 0),
	CONSTRAINT chk_certificates_revocation_pair CHECK (
		(revoked_by IS NULL AND revoked_at IS NULL)
		OR (revoked_by IS NOT NULL AND revoked_at IS NOT NULL)
	)
) ENGINE=InnoDB DEFAULT CHARACTER SET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS admin_settings (
	setting_key VARCHAR(191) NOT NULL,
	setting_value JSON NOT NULL DEFAULT (JSON_OBJECT()),
	updated_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
	created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
	updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6)
		ON UPDATE CURRENT_TIMESTAMP(6),
	PRIMARY KEY (setting_key),
	KEY idx_admin_settings_updated_by (updated_by),
	CONSTRAINT fk_admin_settings_updated_by FOREIGN KEY (updated_by)
		REFERENCES profiles (id) ON DELETE SET NULL,
	CONSTRAINT chk_admin_settings_key CHECK (CHAR_LENGTH(TRIM(setting_key)) > 0)
) ENGINE=InnoDB DEFAULT CHARACTER SET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;